const cfg = $('Set AutoOS Config').first().json;
const today = $now.setZone('Asia/Kolkata').startOf('day');
const num = v => Number(String(v ?? '').replace(/[^\d.]/g, '')) || 0;
const parse = s => { s = String(s || '').trim(); if (!s) return null;
  const m = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);
  const d = m ? DateTime.fromObject({ day: +m[1], month: +m[2], year: +m[3] }, { zone: 'Asia/Kolkata' }) : DateTime.fromISO(s.slice(0, 10), { zone: 'Asia/Kolkata' });
  return d.isValid ? d.startOf('day') : null; };
const sent = new Set($('Read Reminder Log').all().map(i => i.json.reminder_key).filter(Boolean));
const first = n => String(n || '').split(' ')[0] || 'there';
const out = [];
let svcCount = 0, insCount = 0, tdCount = 0, coldCount = 0;

for (const { json: v } of $('Read Vehicles Sheet').all()) {
  if (!v.vehicle_id || /yes|true/i.test(String(v.opted_out || ''))) continue;
  const phone = String(v.phone || '').replace(/\D/g, '');
  if (!phone) continue;
  const purchase = parse(v.purchase_date), last = parse(v.last_service_date) || purchase;
  // ---------- SERVICE ----------
  if (last) {
    const done = num(v.services_done), lastKm = num(v.last_service_km), kmpm = num(v.avg_km_per_month) || cfg.default_km_per_month;
    const daysSince = Math.max(0, Math.floor(today.diff(last, 'days').days));
    const estKm = Math.round(lastKm + kmpm * daysSince / 30.4);
    let kmLeft, daysLeft, label;
    if (done < cfg.free_services.length && purchase) {
      const fs = cfg.free_services[done];
      kmLeft = fs.km - estKm; daysLeft = Math.floor(purchase.plus({ months: fs.months }).diff(today, 'days').days);
      label = `${['1st', '2nd', '3rd'][done]} FREE service`;
    } else {
      const k = Object.keys(cfg.model_intervals).find(x => String(v.model || '').toLowerCase().includes(x));
      const iv = k ? cfg.model_intervals[k] : cfg.default_interval;
      kmLeft = iv.km - (estKm - lastKm); daysLeft = Math.floor(last.plus({ months: iv.months }).diff(today, 'days').days);
      label = 'periodic service';
    }
    const stage = (kmLeft <= -cfg.overdue_km || daysLeft <= -cfg.overdue_days) ? 'overdue'
      : (kmLeft <= 0 || daysLeft <= 0) ? 'due' : (kmLeft <= cfg.due_soon_km || daysLeft <= cfg.due_soon_days) ? 'due_soon' : null;
    if (stage) {
      const bucket = stage === 'overdue' ? `-${Math.min(3, Math.floor(Math.max(-daysLeft, 0) / 14))}` : '';
      const key = `${v.vehicle_id}|svc|${done}|${stage}${bucket}`;
      if (!sent.has(key)) {
        svcCount++;
        const why = kmLeft <= 0 || (kmLeft <= cfg.due_soon_km && daysLeft > cfg.due_soon_days) ? `your ${v.model} has done about ${estKm.toLocaleString('en-IN')} km` : `it's been ${Math.round(daysSince / 30.4)} months since the last service`;
        const head = stage === 'overdue' ? '⚠️ Service overdue' : stage === 'due' ? '🔧 Service due now' : '🔧 Service due soon';
        out.push({ json: { type: 'service', reminder_key: key, ref_id: v.vehicle_id, reg_no: v.reg_no, phone, customer_name: v.customer_name,
          stage, detail: `${label} · est ${estKm} km · ${kmLeft} km / ${daysLeft} days left`,
          message: `${head} – ${v.reg_no}\nHi ${first(v.customer_name)}, ${why}, so your *${label}* is ${stage === 'due_soon' ? 'coming up' : stage === 'due' ? 'due' : 'overdue'}.` +
            `${stage === 'overdue' ? ' Skipping services can affect your warranty and resale value.' : ''}\n\n📅 Book a slot (free pick-up and drop available): ${cfg.booking_link}?reg=${encodeURIComponent(v.reg_no || '')}\n📞 ${cfg.workshop_phone}\n– ${cfg.dealer_name}` } });
      }
    }
  }
  // ---------- INSURANCE ----------
  const exp = parse(v.insurance_expiry);
  if (exp) {
    const d = Math.floor(exp.diff(today, 'days').days);
    if (d <= Math.max(...cfg.insurance_thresholds) && d >= -cfg.insurance_stop_after_days) {
      const th = d < 0 ? 'expired' + (d < -60 ? '-60' : d < -30 ? '-30' : '') : cfg.insurance_thresholds.filter(t => d <= t).sort((a, b) => a - b)[0];
      const key = `${v.vehicle_id}|ins|${exp.toFormat('yyyy-LL-dd')}|${th}`;
      if (!sent.has(key)) {
        insCount++;
        out.push({ json: { type: 'insurance', reminder_key: key, ref_id: v.vehicle_id, reg_no: v.reg_no, phone, customer_name: v.customer_name,
          stage: String(th), urgent: d <= 7, detail: `${v.insurer || 'policy'} expires ${exp.toFormat('dd LLL yyyy')} (${d} days)`,
          message: d < 0
            ? `🚨 Hi ${first(v.customer_name)}, the insurance on *${v.reg_no}* expired ${-d} days ago. Driving uninsured is illegal and risky, and your *No-Claim Bonus is lost after a 90-day lapse*.\nRenew now (inspection arranged if needed): ${cfg.insurance_link}?reg=${encodeURIComponent(v.reg_no || '')}`
            : `🛡️ Hi ${first(v.customer_name)}, the insurance on *${v.reg_no}* (${v.insurer || 'current insurer'}) ${d === 0 ? 'expires *today*' : `expires in *${d} days* (${exp.toFormat('dd LLL')})`}.\nRenew on time to keep your NCB. We'll compare quotes across insurers for you: ${cfg.insurance_link}?reg=${encodeURIComponent(v.reg_no || '')}\n– ${cfg.dealer_name}` } });
      }
    }
  }
}

// ---------- TEST DRIVES ----------
for (const { json: t } of $('Read Test-Drive Leads').all()) {
  if (!t.lead_id || !/open|follow|new|hot|warm/i.test(t.status || 'open')) continue;
  const td = parse(t.test_drive_date); if (!td) continue;
  const days = Math.floor(today.diff(td, 'days').days);
  const sentCount = num(t.followups_sent);
  const idx = cfg.td_schedule.findIndex((d, i) => days >= d && i >= sentCount && (cfg.td_schedule[i + 1] === undefined || days < cfg.td_schedule[i + 1]));
  if (idx < 0) continue;
  tdCount++;
  const cold = cfg.td_schedule[idx] === cfg.td_schedule[cfg.td_schedule.length - 1];
  if (cold) coldCount++;
  out.push({ json: { type: 'test_drive', ref_id: t.lead_id, phone: String(t.phone || '').replace(/\D/g, ''), customer_name: t.name, model: t.model,
    day: cfg.td_schedule[idx], step: idx + 1, days_since: days, cold, salesperson: t.salesperson || '', salesperson_phone: String(t.salesperson_phone || '').replace(/\D/g, ''),
    test_drive_date: td.toFormat('dd LLL'), notes: t.notes || '', budget: t.budget || '', exchange_car: t.exchange_car || '' } });
}
const capped = out.slice(0, cfg.max_reminders_per_run);
capped.push({ json: { type: 'summary', date: today.toFormat('dd LLL yyyy'), service: svcCount, insurance: insCount, test_drive: tdCount,
  cold: coldCount, urgent_insurance: capped.filter(i => i.json.urgent).length, capped: out.length > cfg.max_reminders_per_run } });
return capped;

