const f = $('Post-Service NPS Form').first().json;
const job = $('Look Up Service Job').first()?.json || {};
const ai = $input.first().json.message?.content || {};
const score = Number(f['How likely are you to recommend us? (0 = not at all, 10 = definitely)']);
const band = score <= 6 ? 'detractor' : score <= 8 ? 'passive' : 'promoter';
return [{ json: { ...job, job_card: f.job_card || job.job_card || '', score, band,
  comment: f["What's the main reason for your score?"] || '', callback_ok: f['May our service manager call you?'] === 'Yes',
  sentiment: ai.sentiment || '', categories: (ai.categories || []).join(', '), root_issue: ai.root_issue || '',
  recovery_action: ai.recovery_action || '', apology_message: ai.apology_message || '', urgency: ai.urgency || 'normal',
  // ---- config ----
  service_manager_email: 'REPLACE_WITH_SERVICE_MANAGER_EMAIL', service_manager_whatsapp: 'REPLACE_WITH_SERVICE_MANAGER_NUMBER',
  review_link: 'https://g.page/r/REPLACE_WITH_GOOGLE_REVIEW_ID/review', dealer_name: 'Your Motors' } }];

